    lines = text.splitlines()
    for i, line in enumerate(lines):
        if _FORWARDED.match(line):
            return i, "forward"
        if _ORIGINAL.match(line):
            return i, "original"
        if _REPLY_ON.match(line):
            return i, "reply"
