    sender = _addr(headers.get("from"))
    try:
        date = parsedate_to_datetime(headers["date"]) if headers.get("date") else None
    except Exception:
        date = None
    return Email(
        id=email_id,
        headers=headers,
        body=current,
        forwarded=forwarded,
        quoted=quoted,
        attachments=atts,
        sender=sender,
        internal=sender.endswith("@" + OUR_DOMAIN) or sender.endswith("." + OUR_DOMAIN),
        date=date,
        body_kind=body_kind,
    )

