"""PDF -> Doc. Text pages -> lines (<file>!P<page>L<n>); pages with no text layer -> images.

Encrypted PDFs we cannot open come back as an error (needs review), never a crash.
Struck lines are detected geometrically: a horizontal rule through the middle of the text.
"""

from __future__ import annotations

from io import BytesIO

import pdfplumber
import pypdfium2 as pdfium

from rfq.config import MAX_PDF_PAGES, MAX_SCAN_PAGES, SCAN_DPI
from rfq.extractors.image import to_png
from rfq.models import Doc, ImagePart, Line

MIN_TEXT_CHARS = 20  # fewer chars than this on a page = treat it as a scan


def _h_segments(page) -> list[tuple[float, float, float]]:
    """Horizontal strokes on the page as (x0, x1, y_middle) in top-down coordinates."""
    segs = []
    for ln in page.lines:
        if abs(ln["top"] - ln["bottom"]) < 1.5:
            segs.append((min(ln["x0"], ln["x1"]), max(ln["x0"], ln["x1"]), (ln["top"] + ln["bottom"]) / 2))
    for r in page.rects:
        if r["height"] < 2.0 and r["width"] > 5:
            segs.append((r["x0"], r["x1"], (r["top"] + r["bottom"]) / 2))
    return segs


def _struck(line: dict, segs) -> bool:
    top, bottom, x0, x1 = line["top"], line["bottom"], line["x0"], line["x1"]
    h = bottom - top
    width = max(x1 - x0, 1.0)
    for sx0, sx1, sy in segs:
        if top + 0.3 * h <= sy <= bottom - 0.3 * h:
            overlap = min(x1, sx1) - max(x0, sx0)
            if overlap >= 0.6 * width:
                return True
    return False


def _is_encrypted(data: bytes) -> bool:
    return b"/Encrypt" in data[-4096:] or b"/Encrypt" in data[:4096] or b"/Encrypt" in data


def extract_pdf(name: str, data: bytes) -> Doc:
    doc = Doc(source=name, kind="pdf")
    try:
        pdf = pdfplumber.open(BytesIO(data))
    except Exception as e:
        if _is_encrypted(data):
            doc.error = "PDF is password-protected / encrypted and cannot be opened"
        else:
            doc.error = f"PDF could not be opened ({type(e).__name__})"
        return doc
    scan_pages: list[int] = []
    with pdf:
        n_pages = len(pdf.pages)
        if n_pages > MAX_PDF_PAGES:
            doc.truncated = True
            doc.notes.append(f"PDF has {n_pages} pages; only the first {MAX_PDF_PAGES} were read")
        for p_idx, page in enumerate(pdf.pages[:MAX_PDF_PAGES], start=1):
            if len(page.chars) < MIN_TEXT_CHARS:
                if page.images or len(page.chars) == 0:
                    scan_pages.append(p_idx)
                continue
            segs = _h_segments(page)
            for n, ln in enumerate(page.extract_text_lines(strip=True), start=1):
                text = " ".join(ln["text"].split())
                if text:
                    doc.lines.append(Line(row_id=f"{name}!P{p_idx}L{n}", text=text, struck=_struck(ln, segs)))
    if scan_pages:
        _render_scans(name, data, scan_pages, doc)
    if not doc.lines and not doc.images and not doc.error:
        doc.error = "PDF has no readable text or images"
    return doc


def _render_scans(name: str, data: bytes, pages: list[int], doc: Doc) -> None:
    if len(pages) > MAX_SCAN_PAGES:
        doc.truncated = True
        doc.notes.append(f"{len(pages)} scanned pages; only the first {MAX_SCAN_PAGES} were rendered")
        pages = pages[:MAX_SCAN_PAGES]
    doc.notes.append(f"scanned page(s) {pages} sent as images")
    pdf = pdfium.PdfDocument(data)
    try:
        for p in pages:
            pil = pdf[p - 1].render(scale=SCAN_DPI / 72).to_pil()
            png, w, h = to_png(pil)
            doc.images.append(ImagePart(label=f"{name} page {p}", png=png, width=w, height=h))
    finally:
        pdf.close()

"""Plain-text and HTML attachments -> Doc. Row ids: <file>!L<n>."""

from __future__ import annotations

from rfq.config import MAX_TEXT_LINES
from rfq.extractors.common import decode_text
from rfq.mime import html_to_text
from rfq.models import Doc, Line


def _from_text(name: str, kind: str, text: str) -> Doc:
    doc = Doc(source=name, kind=kind)
    for raw in text.splitlines():
        t = " ".join(raw.split())
        if t:
            if len(doc.lines) >= MAX_TEXT_LINES:
                doc.truncated = True
                doc.notes.append(f"truncated at {MAX_TEXT_LINES} lines")
                break
            doc.lines.append(Line(row_id=f"{name}!L{len(doc.lines) + 1}", text=t))
    return doc


def extract_text(name: str, data: bytes) -> Doc:
    return _from_text(name, "text", decode_text(data))


def extract_html(name: str, data: bytes) -> Doc:
    return _from_text(name, "html", html_to_text(decode_text(data)))

"""Dispatch every part of an email to the right extractor. Nothing here ever raises:
a failure becomes a Doc with `error` set, which later turns into needs_review."""

from __future__ import annotations

import logging
from pathlib import PurePath

from rfq.config import MAX_ATTACHMENT_BYTES, MAX_IMAGES_PER_EMAIL, NESTED_EML_DEPTH
from rfq.extractors.body import extract_body
from rfq.extractors.csv_ import extract_csv
from rfq.extractors.docx_ import extract_docx
from rfq.extractors.image import extract_image
from rfq.extractors.pdf import extract_pdf
from rfq.extractors.text import extract_html, extract_text
from rfq.extractors.xlsx import extract_xlsx
from rfq.models import Attachment, Doc, Email, Line

log = logging.getLogger(__name__)

IMAGE_EXT = {".png", ".jpg", ".jpeg", ".gif", ".bmp", ".tif", ".tiff", ".webp"}


def _kind(att: Attachment) -> str:
    ext = PurePath(att.filename).suffix.lower()
    mime = att.mime.lower()
    if ext in (".xlsx", ".xlsm") or "spreadsheetml" in mime:
        return "xlsx"
    if ext == ".xls" or mime == "application/vnd.ms-excel":
        return "xls"
    if ext in (".csv", ".tsv") or mime in ("text/csv", "text/tab-separated-values"):
        return "csv"
    if ext == ".docx" or "wordprocessingml" in mime:
        return "docx"
    if ext == ".doc" or mime == "application/msword":
        return "doc"
    if ext == ".pdf" or mime == "application/pdf":
        return "pdf"
    if ext in IMAGE_EXT or mime.startswith("image/"):
        return "image"
    if ext == ".eml" or mime == "message/rfc822":
        return "eml"
    if ext in (".htm", ".html") or mime == "text/html":
        return "html"
    if ext in (".txt", ".text") or mime == "text/plain":
        return "text"
    return "unknown"


def _alt_for(att: Attachment, email: Email) -> str:
    return email.image_alts.get(att.content_id or "", "") or email.image_alts.get(att.filename, "")


def extract_attachment(att: Attachment, email: Email, depth: int = 0) -> list[Doc]:
    kind = _kind(att)
    name = att.filename
    if not att.data:
        return [Doc(source=name, kind=kind, error="attachment is empty (0 bytes)")]
    if len(att.data) > MAX_ATTACHMENT_BYTES:
        return [Doc(source=name, kind=kind, error=f"attachment too large ({len(att.data)} bytes)")]
    try:
        if kind == "xlsx":
            return [extract_xlsx(name, att.data)]
        if kind == "csv":
            return [extract_csv(name, att.data)]
        if kind == "docx":
            return [extract_docx(name, att.data)]
        if kind == "pdf":
            return [extract_pdf(name, att.data)]
        if kind == "image":
            return [extract_image(name, att.data, inline=att.inline, alt=_alt_for(att, email))]
        if kind == "html":
            return [extract_html(name, att.data)]
        if kind == "text":
            return [extract_text(name, att.data)]
        if kind == "eml":
            return _extract_eml(att, depth)
        if kind in ("xls", "doc"):
            return [Doc(source=name, kind=kind, error=f"legacy .{kind} format is not supported")]
        return [Doc(source=name, kind=kind, error=f"unsupported attachment type ({att.mime})")]
    except Exception as e:  # corrupt or hostile file: report, never raise
        log.warning("extractor failed on %s/%s: %s", email.id, name, e)
        return [Doc(source=name, kind=kind, error=f"could not read {kind} file ({type(e).__name__}: {e})"[:300])]


def _extract_eml(att: Attachment, depth: int) -> list[Doc]:
    """A message attached inside a message (bounce, forward-as-attachment)."""
    from rfq.mime import parse_message  # local import: mime <-> extractors stay decoupled

    name = att.filename
    inner = parse_message(att.data, f"{name}")
    doc = Doc(source=name, kind="eml")
    h = inner.headers
    hdr = [f"From: {h.get('from')}", f"To: {h.get('to')}", f"Date: {h.get('date')}", f"Subject: {h.get('subject')}"]
    doc.lines += [Line(row_id=f"{name}!H{i}", text=t, style="header") for i, t in enumerate(hdr, 1)]
    body = extract_body(inner)
    for ln in body.lines:
        ln.row_id = ln.row_id.replace("body!", f"{name}!", 1)
    doc.lines += body.lines
    docs = [doc]
    if inner.attachments:
        if depth + 1 >= NESTED_EML_DEPTH:
            doc.notes.append(f"{len(inner.attachments)} nested attachment(s) not opened (depth limit)")
        else:
            for a in inner.attachments:
                docs += extract_attachment(a, inner, depth + 1)
    return docs


def extract_all(email: Email) -> list[Doc]:
    """Body first, then attachments in MIME order. Caps the total images per email."""
    docs = [extract_body(email)]
    for att in email.attachments:
        docs += extract_attachment(att, email)
    n_images = 0
    for d in docs:
        keep = max(0, MAX_IMAGES_PER_EMAIL - n_images)
        if len(d.images) > keep:
            d.notes.append(f"{len(d.images) - keep} image(s) dropped: per-email image cap")
            d.images = d.images[:keep]
            d.truncated = True
        n_images += len(d.images)
    return docs


def describe_docs(docs: list[Doc]) -> str:
    out = []
    for d in docs:
        flags = [f for f, on in (("ERROR", d.error), ("TRUNCATED", d.truncated), ("SKIPPED", d.skipped)) if on]
        out.append(f"--- doc: {d.source} [{d.kind}] {' '.join(flags)}")
        if d.error:
            out.append(f"    error: {d.error}")
        for n in d.notes:
            out.append(f"    note: {n}")
        for im in d.images:
            out.append(f"    image: {im.label} {im.width}x{im.height} {len(im.png)} bytes")
        for ln in d.lines:
            tags = "".join(
                [" ~STRUCK~" if ln.struck else "", f" ({ln.style})" if ln.style else "",
                 f" [{ln.note}]" if ln.note else ""]
            )
            out.append(f"    [{ln.row_id}] {ln.text}{tags}")
    return "\n".join(out) + "\n"

