"""Small helpers shared by extractors."""

from __future__ import annotations

from datetime import date, datetime


def fmt_value(v: object) -> str:
    """Cell value -> text as a person would read it (12.0 -> "12", dates -> ISO)."""
    if v is None:
        return ""
    if isinstance(v, bool):
        return str(v)
    if isinstance(v, float):
        return str(int(v)) if v.is_integer() else f"{v:g}"
    if isinstance(v, datetime):
        return v.date().isoformat() if v.time() == datetime.min.time() else v.isoformat(" ")
    if isinstance(v, date):
        return v.isoformat()
    return " ".join(str(v).split())


def row_text(cells: list[str]) -> str:
    """Cells -> one line. Leading empty cells are kept so columns stay aligned with the header;
    trailing ones are dropped."""
    while cells and not cells[-1]:
        cells = cells[:-1]
    return " | ".join(cells)


def decode_text(data: bytes) -> str:
    for enc in ("utf-8-sig", "cp1252"):
        try:
            return data.decode(enc)
        except UnicodeDecodeError:
            continue
    return data.decode("utf-8", "replace")

"""Excel (.xlsx/.xlsm) -> Doc. Row ids: <sheet>!R<row>.

Keeps what an ISR would use: sheet names (often carry the spec), merged banner notes,
cell comments. Skips hidden sheets, rows and columns (noted, not silently). Marks struck rows.
"""

from __future__ import annotations

from io import BytesIO

import openpyxl

from rfq.config import MAX_ROWS_PER_SHEET
from rfq.extractors.common import fmt_value, row_text
from rfq.models import Doc, Line


def extract_xlsx(name: str, data: bytes) -> Doc:
    doc = Doc(source=name, kind="xlsx")
    wb = openpyxl.load_workbook(BytesIO(data), data_only=True)
    visible = [ws for ws in wb.worksheets if ws.sheet_state == "visible"]
    for ws in wb.worksheets:
        if ws.sheet_state != "visible":
            doc.notes.append(f"hidden sheet {ws.title!r} skipped")
    if len(visible) > 1:
        doc.notes.append(
            f"{len(visible)} visible sheets, in workbook order: "
            + ", ".join(repr(ws.title) for ws in visible)
        )
    for ws in visible:
        _sheet(ws, doc)
    if not doc.lines:
        doc.notes.append("workbook has no visible content")
    return doc


def _sheet(ws, doc: Doc) -> None:
    hidden_cols = {k for k, d in ws.column_dimensions.items() if d.hidden}
    hidden_rows = {r for r, d in ws.row_dimensions.items() if d.hidden}
    if hidden_rows:
        doc.notes.append(f"sheet {ws.title!r}: {len(hidden_rows)} hidden row(s) skipped")
    if hidden_cols:
        doc.notes.append(f"sheet {ws.title!r}: hidden column(s) {sorted(hidden_cols)} skipped")
    for rng in ws.merged_cells.ranges:
        doc.notes.append(f"sheet {ws.title!r}: merged cells {rng}")

    n_rows = 0
    for row in ws.iter_rows():
        r = row[0].row
        if r in hidden_rows:
            continue
        if n_rows >= MAX_ROWS_PER_SHEET:
            doc.truncated = True
            doc.notes.append(f"sheet {ws.title!r} truncated at {MAX_ROWS_PER_SHEET} rows")
            break
        cells, struck_cells = [], []
        for c in row:
            if c.column_letter in hidden_cols:
                continue
            text = fmt_value(c.value)
            cells.append(text)
            if text and c.font is not None and c.font.strike:
                struck_cells.append(c.coordinate)
            if c.comment and c.comment.text.strip():
                doc.notes.append(f"{ws.title}!{c.coordinate} comment: {c.comment.text.strip()}")
        filled = [x for x in cells if x]
        if not filled:
            continue
        n_rows += 1
        whole = len(struck_cells) == len(filled)
        doc.lines.append(
            Line(
                row_id=f"{ws.title}!R{r}",
                text=row_text(cells),
                cells=cells,
                struck=whole,
                note=(f"struck cells: {', '.join(struck_cells)}" if struck_cells and not whole else None),
            )
        )

"""Word (.docx) -> Doc, walking the body in document order so headings stay above their tables.

Row ids: <file>!P<n> paragraphs, <file>!T<t>R<r> table rows, <file>!H<n> header/footer text.
Tracked deletions (w:del) are dropped; struck-through runs are marked.
"""

from __future__ import annotations

from io import BytesIO

import docx
from docx.oxml.ns import qn

from rfq.config import MAX_TEXT_LINES
from rfq.extractors.common import row_text
from rfq.models import Doc, Line

W_P, W_TBL, W_TR, W_TC, W_R, W_T, W_DEL = (
    qn("w:p"), qn("w:tbl"), qn("w:tr"), qn("w:tc"), qn("w:r"), qn("w:t"), qn("w:del")
)


def _is_struck(run) -> bool:
    rpr = run.find(qn("w:rPr"))
    if rpr is None:
        return False
    for tag in ("w:strike", "w:dstrike"):
        el = rpr.find(qn(tag))
        if el is not None and el.get(qn("w:val"), "true").lower() not in ("false", "0", "off"):
            return True
    return False


def _para_text(p) -> tuple[str, bool]:
    """Text of a paragraph (incl. tracked insertions, excl. deletions) and whether all of it is struck."""
    parts, struck_chars, total_chars = [], 0, 0
    for run in p.iter(W_R):
        if any(anc.tag == W_DEL for anc in run.iterancestors()):
            continue
        t = "".join(x.text or "" for x in run.iter(W_T))
        if not t:
            continue
        parts.append(t)
        n = len(t.strip())
        total_chars += n
        if _is_struck(run):
            struck_chars += n
    text = " ".join("".join(parts).split())
    return text, bool(total_chars) and struck_chars == total_chars


def _style(p, d) -> str | None:
    ppr = p.find(qn("w:pPr"))
    if ppr is None:
        return None
    ps = ppr.find(qn("w:pStyle"))
    if ps is None:
        return None
    sid = ps.get(qn("w:val"))
    try:
        return d.styles.get_by_id(sid, 1).name if sid else None  # 1 = WD_STYLE_TYPE.PARAGRAPH
    except Exception:
        return sid


def extract_docx(name: str, data: bytes) -> Doc:
    doc = Doc(source=name, kind="docx")
    d = docx.Document(BytesIO(data))
    n_p = n_t = 0
    for block in d.element.body.iterchildren():
        if block.tag == W_P:
            text, struck = _para_text(block)
            if text:
                n_p += 1
                style = _style(block, d)
                doc.lines.append(Line(row_id=f"{name}!P{n_p}", text=text, struck=struck,
                                      style=style if style and style != "Normal" else None))
        elif block.tag == W_TBL:
            n_t += 1
            for r_idx, tr in enumerate(block.iter(W_TR), start=1):
                cells, struck_flags = [], []
                for tc in tr.findall(W_TC):
                    paras = [_para_text(p) for p in tc.iter(W_P)]
                    cells.append(" ".join(t for t, _ in paras if t))
                    struck_flags.append(bool(paras) and all(s for t, s in paras if t) and any(t for t, _ in paras))
                if not any(cells):
                    continue
                filled = [(c, s) for c, s in zip(cells, struck_flags) if c]
                whole = all(s for _, s in filled)
                some = any(s for _, s in filled)
                doc.lines.append(Line(
                    row_id=f"{name}!T{n_t}R{r_idx}", text=row_text(cells), cells=cells, struck=whole,
                    note="some cells struck" if some and not whole else None,
                ))
        if len(doc.lines) > MAX_TEXT_LINES:
            doc.truncated = True
            doc.notes.append(f"truncated at {MAX_TEXT_LINES} lines")
            break
    n_h = 0
    for sec in d.sections:
        for part in (sec.header, sec.footer):
            for p in part.paragraphs:
                text = " ".join(p.text.split())
                if text:
                    n_h += 1
                    doc.lines.append(Line(row_id=f"{name}!H{n_h}", text=text, style="header/footer"))
    return doc

