    return {k: tuple(vals) for k, vals in v.items()}


# ---------------------------------------------------------------- sizes
_NUM = re.compile(r"^(\d+)?(?:[\s-]*(\d+)/(\d+))?$|^(\d+(?:\.\d+)?)$")


def _part_value(s: str) -> Fraction | str | None:
    s = s.strip().lower().replace("″", "").replace('"', "").replace("''", "")
    s = re.sub(r"\s*(in|inch|inches)$", "", s).strip()
    if not s:
