"""Collect distinctive strings from data/dev and search rfq/ for them (read-only)."""
import email, json, re, sys
from email import policy
from pathlib import Path
dev = Path("data/dev/emails")
terms = {}  # term -> where from
def add(t, why):
    t = t.strip()
    if len(t) >= 4: terms.setdefault(t, why)
for p in sorted(dev.glob("*.eml")):
    m = email.message_from_bytes(p.read_bytes(), policy=policy.default)
    add(p.stem, "email id")
    for h in ("From", "To", "Cc", "Subject"):
        v = str(m.get(h) or "")
        for a in re.findall(r"[\w.+-]+@([\w.-]+)", v): add(a.split(".")[0], f"{p.stem} {h} domain")
        for n in re.findall(r"\b[A-Z][a-z]{3,}\b", v): add(n, f"{p.stem} {h} word")
        if h == "Subject": add(v, f"{p.stem} subject")
    for part in m.walk():
        fn = part.get_filename()
        if fn: add(Path(fn).stem, f"{p.stem} attachment name")
    txt = p.read_text(encoding="utf-8", errors="ignore")
    for c in re.findall(r"\b(?=[A-Z0-9-]*\d)(?=[A-Z0-9-]*[A-Z])[A-Z0-9]+(?:-[A-Z0-9]+)+\b", txt): add(c, f"{p.stem} code")
key = json.loads(Path("data/dev/answer_key.json").read_text(encoding="utf-8"))["emails"]
for eid, e in key.items():
    for li in e.get("line_items", []):
        add(li["raw"], f"{eid} answer-key raw")
        for c in re.findall(r"\b[A-Z0-9]+(?:-[A-Z0-9]+)+\b", li["raw"]): add(c, f"{eid} answer-key code")
files = [f for f in Path("rfq").rglob("*.py")]
hits = []
for f in files:
    lines = f.read_text(encoding="utf-8").splitlines()
    for i, ln in enumerate(lines, 1):
        for t, why in terms.items():
            if re.search(r"(?<![A-Za-z0-9])" + re.escape(t) + r"(?![A-Za-z0-9])", ln, re.I):
                hits.append((str(f), i, t, why, ln.strip()[:140]))
print(len(terms), "dev terms searched in", len(files), "files")
for h in hits: print(f"{h[0]}:{h[1]}  [{h[2]}] ({h[3]})\n      {h[4]}")
EOF
.venv/Scripts/python "$TEMP/claude/devterms.py"

