        num = re.search(r"\d+", value)
        return bool(num) and num.group(0) in re.findall(r"\d+", t)
    if attr == "extra":
        return value.lower() in t
    cores = _cores(value)
    return any(c in toks or c in t for c in cores) if cores else False

